window.DP.L10N["uk"] = {"ui":{"Velikost písma: {v}":"Розмір шрифту: {v}","Váš prohlížeč neumí číst nahlas.":"Ваш браузер не вміє читати вголос.","Zastavit čtení":"Зупинити читання","Přečíst nahlas":"Прочитати вголос","Mluvit":"Говорити","Poslouchám… klepněte pro konec":"Слухаю… торкніться, щоб завершити","Tento prohlížeč diktování neumí. Klepněte do pole a použijte mikrofon na klávesnici telefonu.":"Цей браузер не підтримує диктування. Торкніться поля і скористайтеся мікрофоном на клавіатурі телефона.","Povolte prosím mikrofon pro tuto stránku v nastavení prohlížeče.":"Будь ласка, дозвольте мікрофон для цієї сторінки в налаштуваннях браузера.","Diktování je vypnuté. Na iPhonu zapněte Siri a diktování v Nastavení, nebo použijte mikrofon na klávesnici.":"Диктування вимкнено. На iPhone увімкніть Siri і диктування в Налаштуваннях або скористайтеся мікрофоном на клавіатурі.","Nic jsem neslyšel. Klepněte na Mluvit a mluvte prosím blíž k telefonu.":"Я нічого не почув. Торкніться «Говорити» і говоріть, будь ласка, ближче до телефона.","Nenašel jsem mikrofon. Zkontrolujte, že ho nepoužívá jiná aplikace.":"Я не знайшов мікрофон. Перевірте, чи його не використовує інша програма.","Diktování potřebuje internet. Zkuste to znovu, nebo dotaz napište.":"Для диктування потрібен інтернет. Спробуйте ще раз або напишіть запитання.","Diktování v tomto jazyce tu není dostupné. Použijte mikrofon na klávesnici.":"Диктування цією мовою тут недоступне. Скористайтеся мікрофоном на клавіатурі.","Zkontrolujte prosím text. Pokud sedí, stiskněte tlačítko pro odeslání.":"Будь ласка, перевірте текст. Якщо все правильно, натисніть кнопку надсилання.","Diktování se nepodařilo spustit. Zkuste to prosím znovu.":"Не вдалося запустити диктування. Спробуйте ще раз.","Zavolat":"Зателефонувати","Dobré ráno!":"Доброго ранку!","Dobrý večer!":"Добрий вечір!","Dobrý den!":"Добрий день!","Napište prosím svůj dotaz.":"Будь ласка, напишіть своє запитання.","Napište, s čím potřebujete pomoct":"Напишіть, з чим вам потрібна допомога","Zeptat se":"Запитати","Volá mi někdo z banky":"Мені телефонує хтось із банку","Přišla mi divná SMS o balíku":"Мені прийшла дивна SMS про посилку","Co je Facebook?":"Що таке Facebook?","Jak poslat fotku vnoučatům?":"Як надіслати фото онукам?","Zapomněl/a jsem heslo":"Я забув/забула пароль","Telefon se rychle vybíjí":"Телефон швидко розряджається","Váš vlídný průvodce":"Ваш доброзичливий помічник","S čím vám mohu dnes pomoci?":"Чим я можу вам сьогодні допомогти?","Technologie bez stresu, spěchu a obav. Vše vysvětlíme česky, pomalu a krok za krokem.":"Технології без стресу, поспіху й страху. Усе пояснимо повільно, крок за кроком.","Například: Jak poslat fotku?":"Наприклад: Як надіслати фото?","Usměvavá paní s brýlemi drží chytrý telefon.":"Усміхнена пані в окулярах тримає смартфон.","Bez obav":"Без страху","Technologie bez stresu":"Технології без стресу","Ptejte se snadno":"Запитуйте легко","Žádná otázka není hloupá. Napište ji, nebo ji řekněte nahlas tlačítkem ":"Немає дурних запитань. Напишіть його або скажіть уголос кнопкою ","Hlavní pomocníci":"Головні помічники","Zeptejte se":"Запитайте","Rozhovor s parťákem. Přednostně odpovídá ověřenými radami, jiné odpovědi jasně označí.":"Розмова з помічником. Спершу відповідає перевіреними порадами, інші відповіді чітко позначає.","Otevřít rozhovor":"Відкрити розмову","Žádná otázka není hloupá":"Немає дурних запитань","Je to podvod?":"Це шахрайство?","Přišla vám divná SMS nebo e-mail? Společně zkontrolujeme varovné znaky.":"Отримали дивну SMS чи e-mail? Разом перевіримо тривожні ознаки.","Zkontrolovat zprávu":"Перевірити повідомлення","Text nikam neodesíláme":"Ми нікуди не надсилаємо ваш текст","Krok za krokem":"Крок за кроком","Jednoduché návody. Vždy jen jeden krok na obrazovce.":"Прості інструкції. На екрані завжди лише один крок.","Prohlédnout návody":"Переглянути інструкції","Pomalu, jak vám vyhovuje":"У зручному для вас темпі","Časté otázky":"Часті запитання","Klepněte a hned dostanete odpověď.":"Торкніться — і одразу отримаєте відповідь.","Vaše bezpečí je na 1. místě":"Ваша безпека — на першому місці","Nikdy po vás nechceme hesla, PIN ani číslo karty.":"Ми ніколи не просимо ваші паролі, PIN чи номер картки.","Parťák odpovídá z knihovny ověřených rad. Každou jinou odpověď jasně označí, abyste si ji mohli ověřit.":"Помічник відповідає з бібліотеки перевірених порад. Будь-яку іншу відповідь він чітко позначає, щоб ви могли її перевірити.","Vaše dotazy zůstávají jen ve vašem zařízení.":"Ваші запитання залишаються лише на вашому пристрої.","Usměvavý pán s brýlemi pracuje na tabletu.":"Усміхнений пан в окулярах працює на планшеті.","Chcete mluvit s člověkem?":"Хочете поговорити з людиною?","Senior telefon je zdarma a nonstop.":"Senior telefon (чеська лінія для літніх людей) безкоштовний і цілодобовий.","Další čísla pomoci":"Інші номери допомоги","Přizpůsobit aplikaci":"Налаштувати застосунок","Velikost písma, vysoký kontrast, čtení nahlas":"Розмір шрифту, високий контраст, читання вголос","Rozhovor s DIGI parťákem":"Розмова з DIGI parťák","Napište svůj dotaz…":"Напишіть своє запитання…","Zeptejte se parťáka":"Запитайте помічника","Ověřené rady mají zelený štítek":"Перевірені поради мають зелену позначку","Rozhovor jsem smazal.":"Я видалив розмову.","Nový rozhovor":"Нова розмова","Do chatu nikdy nepište hesla, PIN ani číslo karty. Rozhovor se neukládá a po zavření aplikace zmizí.":"Ніколи не пишіть у чат паролі, PIN чи номер картки. Розмова не зберігається і зникає після закриття застосунку.","Váš dotaz":"Ваше запитання","Odeslat":"Надіслати","Myslíte jedno z těchto témat?":"Ви маєте на увазі одну з цих тем?","Promiňte, nerozuměl jsem.":"Вибачте, я не зрозумів.","Promiňte, na tohle teď nemám odpověď.":"Вибачте, зараз я не маю на це відповіді.","V aplikaci to nemám, hledám odpověď mimo aplikaci…":"У застосунку цього немає, шукаю відповідь поза застосунком…","Nenašli jste, co jste hledali?":"Не знайшли, що шукали?","Zeptat se mimo aplikaci":"Запитати поза застосунком","Pozor: {t}":"Увага: {t}","DIGI parťák říká: ":"DIGI parťák каже: ","Vy: ":"Ви: ","Dobrý den! Jsem DIGI parťák.":"Добрий день! Я — DIGI parťák.","Zeptejte se vlastními slovy, nebo si vyberte téma. Nejdřív hledám v knihovně ověřených rad. Když tam odpověď není, zkusím poradit jinak – ale vždy vás upozorním, ať si to ověříte.":"Запитуйте своїми словами або оберіть тему. Спершу я шукаю в бібліотеці перевірених порад. Якщо відповіді там немає, спробую допомогти інакше — але завжди нагадаю, щоб ви це перевірили.","Dobrý den! Jsem DIGI parťák. Zeptejte se vlastními slovy, nebo si vyberte téma.":"Добрий день! Я — DIGI parťák. Запитуйте своїми словами або оберіть тему.","číslo karty":"номер картки","rodné číslo":"ідентифікаційний номер (чеське rodné číslo)","heslo nebo kód":"пароль або код"," Pozor na citlivé údaje":" Обережно з чутливими даними","Ve vaší zprávě bylo {what}. Skryl jsem to a nikam se to neodeslalo.":"Ваше повідомлення містило: {what}. Я це приховав, і нікуди це не надіслано.","Tyto údaje prosím nikdy nikomu nepište – ani do chatu, ani do SMS či e-mailu.":"Будь ласка, ніколи нікому не пишіть ці дані — ні в чат, ні в SMS чи e-mail.","Jste bez internetu.":"Ви без інтернету.","Bez internetu umím odpovídat jen z knihovny ověřených rad. Vyberte si téma, nebo to zkuste znovu, až budete připojeni.":"Без інтернету я можу відповідати лише з бібліотеки перевірених порад. Оберіть тему або спробуйте знову, коли будете в мережі.","V ověřené knihovně to není a odpověď mimo aplikaci se teď nepodařilo získat. Zkuste to za chvíli, napište to jinými slovy, nebo se zeptejte člověka.":"У перевіреній бібліотеці цього немає, а відповідь поза застосунком зараз отримати не вдалося. Спробуйте за хвилину, напишіть інакше або запитайте людину.","Zkuste to napsat jinými slovy, vyberte si téma, nebo se zeptejte člověka.":"Спробуйте написати іншими словами, оберіть тему або запитайте людину.","Možná hledáte:":"Можливо, ви шукаєте:","Senior telefon 800 157 157":"Senior telefon 800 157 157","Promiňte, na tohle nemám ověřenou odpověď. Nechci vám radit nepřesně.":"Вибачте, на це я не маю перевіреної відповіді. Не хочу радити неточно.","Informace mimo aplikaci – ověřte si ji":"Інформація поза застосунком — перевірте її","Tohle v ověřené knihovně DIGI parťáka není. Odpověď připravila umělá inteligence z obecných znalostí. Může obsahovat chybu nebo být zastaralá.":"Цього немає в перевіреній бібліотеці DIGI parťák. Відповідь підготував штучний інтелект на основі загальних знань. Вона може містити помилку або бути застарілою.","Jak si to ověřit:":"Як це перевірити:","Zeptejte se blízkého člověka, kterému věříte.":"Запитайте близьку людину, якій ви довіряєте.","Podívejte se na oficiální web instituce – adresu napište sami.":"Подивіться на офіційний сайт установи — адресу введіть самі.","Zavolejte bezplatně na Senior telefon 800 157 157.":"Зателефонуйте безкоштовно на Senior telefon 800 157 157 (чеська лінія).","Než cokoli zaplatíte nebo nainstalujete, nejdřív si informaci ověřte.":"Перш ніж щось оплатити чи встановити, спершу перевірте інформацію."," Důležité – jednejte hned":" Важливо — дійте негайно","Ověřená rada":"Перевірена порада","Odkud to víme":"Звідки ми це знаємо","Mohlo by vás zajímat:":"Вас також може зацікавити:","Sem vložte nebo opište text podezřelé zprávy…":"Вставте або перепишіть сюди текст підозрілого повідомлення…","Nejdřív prosím vložte text zprávy.":"Спершу, будь ласка, вставте текст повідомлення.","Text jsem vložil.":"Я вставив текст.","Schránka je prázdná.":"Буфер обміну порожній.","Vložte text podržením prstu v poli a volbou „Vložit“.":"Вставте текст: утримуйте палець у полі й оберіть «Вставити».","Vložit zkopírovaný text":"Вставити скопійований текст","Vložte text podezřelé zprávy, nebo nahrajte její fotku či snímek obrazovky. Ukážu vám varovné znaky a poradím, co bezpečně udělat.":"Вставте текст підозрілого повідомлення або завантажте його фото чи знімок екрана. Я покажу тривожні ознаки й підкажу, як безпечно діяти.","Zkontrolovat fotku zprávy":"Перевірити фото повідомлення","Udělejte snímek obrazovky podezřelé SMS, e-mailu nebo zprávy a nahrajte ho sem. Můžete zprávu i vyfotit jiným telefonem.":"Зробіть знімок екрана підозрілої SMS, e-mail чи повідомлення і завантажте його сюди. Можна також сфотографувати повідомлення іншим телефоном.","Nahrát snímek obrazovky":"Завантажити знімок екрана","Vyfotit zprávu":"Сфотографувати повідомлення","Fotka se odešle k rozboru umělé inteligenci (Claude od firmy Anthropic). Nikde ji neukládáme. Číslo karty nebo kódy na fotce raději zakryjte.":"Фото буде надіслано на аналіз штучному інтелекту (Claude від компанії Anthropic). Ми ніде його не зберігаємо. Номер картки чи коди на фото краще закрийте.","Nevíte, jak udělat snímek obrazovky? ":"Не знаєте, як зробити знімок екрана? ","Návod pro Android":"Інструкція для Android","Návod pro iPhone":"Інструкція для iPhone","Nebo vložte text zprávy":"Або вставте текст повідомлення","Text zprávy":"Текст повідомлення","Kontrola textu probíhá jen ve vašem zařízení. Text nikam neodesíláme.":"Перевірка тексту відбувається лише на вашому пристрої. Ми нікуди не надсилаємо текст.","Zkontrolovat text":"Перевірити текст","Vymazat":"Очистити","Vyzkoušet na ukázkové podvodné SMS":"Спробувати на прикладі шахрайської SMS","Zlaté pravidlo":"Золоте правило","Když zpráva spěchá a chce peníze nebo údaje – ":"Коли повідомлення квапить і хоче грошей чи даних — ","zastavte se a ověřte si to sami.":"зупиніться й перевірте це самі.","Zavolejte bance, poště nebo úřadu na číslo z jejich oficiálního webu nebo z platební karty – nikdy na číslo či odkaz ze zprávy.":"Зателефонуйте в банк, на пошту чи в установу за номером з їхнього офіційного сайту або з платіжної картки — ніколи за номером чи посиланням з повідомлення.","Vyberte prosím obrázek.":"Будь ласка, оберіть зображення.","Obrázek je moc velký. Zkuste udělat snímek obrazovky.":"Зображення завелике. Спробуйте зробити знімок екрана.","Tento obrázek neumím otevřít. Zkuste snímek obrazovky ve formátu JPG nebo PNG.":"Я не можу відкрити це зображення. Спробуйте знімок екрана у форматі JPG або PNG.","Prohlížím fotku… může to trvat až půl minuty.":"Переглядаю фото… це може тривати до пів хвилини.","Náhled nahrané fotky zprávy":"Попередній перегляд завантаженого фото повідомлення","Jste bez internetu. Rozbor fotky potřebuje internet – zkuste prosím opsat text zprávy do pole níže.":"Ви без інтернету. Для аналізу фото потрібен інтернет — перепишіть, будь ласка, текст повідомлення в поле нижче.","Rozbor fotky se teď nepodařil. Zkuste to prosím za chvíli, nebo opište text zprávy do pole níže.":"Аналіз фото зараз не вдався. Спробуйте за хвилину або перепишіть текст повідомлення в поле нижче.","Velmi podezřelé!":"Дуже підозріло!","Zpráva má několik typických znaků podvodu. Na nic neklikejte a nic neplaťte.":"Повідомлення має кілька типових ознак шахрайства. Нічого не натискайте й нічого не оплачуйте.","Buďte opatrní":"Будьте обережні","Našel jsem varovné znaky. Než cokoli uděláte, ověřte si zprávu jinou cestou.":"Я знайшов тривожні ознаки. Перш ніж щось робити, перевірте повідомлення іншим шляхом.","Nenašel jsem typické znaky podvodu":"Я не знайшов типових ознак шахрайства","To ale neznamená, že je zpráva určitě v pořádku. Podvodníci vymýšlejí stále nové triky.":"Але це не означає, що повідомлення точно в порядку. Шахраї постійно вигадують нові трюки.","Fotku se nepodařilo posoudit":"Фото не вдалося оцінити","Na fotce nevidím čitelnou zprávu. Zkuste ostřejší snímek obrazovky, na kterém je celý text, nebo text opište do pole.":"На фото я не бачу читабельного повідомлення. Спробуйте чіткіший знімок екрана з усім текстом або перепишіть текст у поле.","Pokud vás zpráva o něco žádá, ověřte si to u odesílatele na známém čísle.":"Якщо повідомлення про щось просить, перевірте це у відправника за відомим номером.","Nikdy nezadávejte PIN, hesla ani kódy z SMS přes odkaz.":"Ніколи не вводьте PIN, паролі чи коди з SMS за посиланням.","Na odkaz ve zprávě neklikejte a neodpovídejte.":"Не натискайте посилання в повідомленні й не відповідайте.","Ověřte si to sami – zavolejte na oficiální číslo instituce nebo blízkému člověku.":"Перевірте самі — зателефонуйте на офіційний номер установи або близькій людині.","Zprávu smažte a odesílatele zablokujte.":"Видаліть повідомлення й заблокуйте відправника.","Pokud jste už něco vyplnili nebo zaplatili, hned volejte svou banku.":"Якщо ви вже щось заповнили чи оплатили, негайно телефонуйте у свій банк.","Rozbor fotky pomocí umělé inteligence. Výsledek je orientační, ověřte si ho. ":"Аналіз фото за допомогою штучного інтелекту. Результат орієнтовний, перевірте його. ","Co udělat: {t}":"Що робити: {t}","Rozbor fotky pomocí umělé inteligence":"Аналіз фото за допомогою штучного інтелекту","Výsledek je orientační a může obsahovat chybu. Když si nejste jistí, ověřte si to u blízkého nebo na Senior telefonu 800 157 157.":"Результат орієнтовний і може містити помилку. Якщо ви не впевнені, перевірте це в близької людини або на Senior telefon 800 157 157.","Výsledek kontroly":"Результат перевірки","Čeho jsem si všiml:":"Що я помітив:","Co teď bezpečně udělat:":"Що зараз безпечно зробити:","Text, který jsem na fotce přečetl":"Текст, який я прочитав на фото","Už jsem klikl/a – co teď?":"Я вже натиснув/натиснула — що тепер?","Návody krok za krokem":"Інструкції крок за кроком","Vyberte si, co se chcete naučit. Na každé obrazovce je jen jeden krok. Můžete se kdykoli vrátit.":"Оберіть, чого хочете навчитися. На кожному екрані лише один крок. Ви можете будь-коли повернутися.","{n} kroků · asi {m} min":"{n} кроків · приблизно {m} хв","Všechny návody":"Усі інструкції","Začít":"Почати","Zdroj: {t}":"Джерело: {t}","Postup návodem":"Перебіг інструкції","Krok {i} z {n}":"Крок {i} з {n}","Tip: ":"Порада: ","Krok {i}":"Крок {i}","Zvládli jste to!":"У вас вийшло!","Výborně. Návod si můžete kdykoli zopakovat.":"Чудово. Інструкцію можна будь-коли повторити.","Zpět":"Назад","Další krok":"Наступний крок","Hotovo":"Готово","Pomoc a důležitá čísla":"Допомога та важливі номери","Klepnutím na číslo rovnou zavoláte. Ve vážné situaci neváhejte – raději zavolejte.":"Торкніться номера, щоб одразу зателефонувати. У серйозній ситуації не вагайтеся — краще зателефонуйте.","Tísňová volání":"Екстрені виклики","Když potřebujete poradit nebo si promluvit":"Коли потрібна порада чи розмова"," Ztratili jste kartu nebo vás někdo okradl?":" Загубили картку або вас обікрали?","Hned zavolejte do své banky a kartu zablokujte. Číslo najdete na webu banky nebo ve smlouvě.":"Негайно зателефонуйте у свій банк і заблокуйте картку. Номер знайдете на сайті банку або в договорі.","Krádež nebo podvod oznamte Policii ČR na čísle 158.":"Про крадіжку чи шахрайство повідомте чеську поліцію за номером 158.","Čísla připravena podle oficiálních zdrojů (IZS, Život 90, Elpida). Před zveřejněním aplikace je ověřte.":"Номери підготовлено за офіційними джерелами (IZS, Život 90, Elpida). Перевірте їх перед публікацією застосунку.","zapnuto":"увімкнено","vypnuto":"вимкнено","Zapnuto":"Увімкнено","Vypnuto":"Вимкнено","Nastavení":"Налаштування","Upravte si parťáka tak, aby se vám dobře četl a používal.":"Налаштуйте помічника так, щоб вам було зручно читати й користуватися.","Jazyk":"Мова","Velikost písma":"Розмір шрифту","Ukázka: Takhle velké bude písmo v celé aplikaci.":"Приклад: такого розміру буде текст у всьому застосунку.","Vysoký kontrast":"Високий контраст","Výraznější barvy a silnější okraje pro horší zrak.":"Виразніші кольори й товщі рамки для слабшого зору.","Číst odpovědi nahlas":"Читати відповіді вголос","Parťák vám každou odpověď v chatu sám přečte.":"Помічник сам прочитає вам кожну відповідь у чаті.","Pomalejší čtení":"Повільніше читання","Hlas bude mluvit pomaleji a zřetelněji.":"Голос говоритиме повільніше й чіткіше.","Parťák na ploše telefonu":"DIGI parťák на головному екрані"," Aplikace je nainstalovaná. Výborně!":" Застосунок встановлено. Чудово!","Přidejte si DIGI parťáka na plochu. Otevřete ho pak jedním klepnutím, jako každou jinou aplikaci.":"Додайте DIGI parťák на головний екран. Тоді ви відкриватимете його одним дотиком, як будь-який інший застосунок.","Hotovo! Parťák je na ploše.":"Готово! DIGI parťák на головному екрані.","Přidat na plochu":"Додати на головний екран","Návod krok za krokem":"Інструкція крок за кроком","Soukromí a bezpečí":"Приватність і безпека","Aplikace nemá žádný účet ani registraci.":"Застосунок не має облікового запису й реєстрації.","Kontrola vloženého textu v sekci „Je to podvod?“ probíhá jen ve vašem zařízení. Rozhovory se neukládají a po zavření zmizí.":"Перевірка вставленого тексту в розділі «Це шахрайство?» відбувається лише на вашому пристрої. Розмови не зберігаються й зникають після закриття.","V zařízení si pamatujeme jen vaše nastavení (velikost písma, kontrast).":"На пристрої ми пам'ятаємо лише ваші налаштування (розмір шрифту, контраст, мову).","Když otázka není v knihovně ověřených rad, odešle se (bez čísel karet, PINů a hesel) k zodpovězení umělé inteligenci Claude od firmy Anthropic. Taková odpověď je vždy označená „Informace mimo aplikaci“. Stejně tak se k rozboru odešle fotka zprávy, kterou nahrajete v sekci „Je to podvod?“. Nic z toho neukládáme.":"Якщо запитання немає в бібліотеці перевірених порад, його буде надіслано (без номерів карток, PIN і паролів) штучному інтелекту Claude від компанії Anthropic. Така відповідь завжди позначена «Інформація поза застосунком». Так само на аналіз надсилається фото повідомлення, яке ви завантажите в розділі «Це шахрайство?». Ми нічого з цього не зберігаємо.","Funkci „Mluvit“ zajišťuje váš prohlížeč (např. Google nebo Apple), který může hlas zpracovat na svém serveru.":"Функцію «Говорити» забезпечує ваш браузер (наприклад, Google або Apple), який може обробляти голос на своєму сервері.","Opravdu smazat nastavení a rozhovor? Aplikace se vrátí do výchozího stavu.":"Справді видалити налаштування й розмову? Застосунок повернеться до початкового стану.","Vše jsem smazal.":"Я все видалив.","Smazat vše z tohoto zařízení":"Видалити все з цього пристрою","O aplikaci":"Про застосунок","DIGI parťák je trpělivý digitální průvodce pro seniory. Chatbot nejdřív hledá v knihovně předem připravených a zkontrolovaných rad s uvedenými zdroji. Teprve když tam odpověď není, odpoví pomocí umělé inteligence – takovou odpověď vždy výrazně označí jako neověřenou.":"DIGI parťák — терплячий цифровий помічник для літніх людей. Чат-бот спершу шукає в бібліотеці заздалегідь підготовлених і перевірених порад із зазначеними джерелами. Лише коли відповіді там немає, він відповідає за допомогою штучного інтелекту — і завжди чітко позначає таку відповідь як неперевірену.","Parťák nenahrazuje lékaře, banku, policii ani právníka. Ve vážné situaci volejte 112.":"DIGI parťák не замінює лікаря, банк, поліцію чи юриста. У серйозній ситуації телефонуйте 112.","Stav knihovny rad: {s}. Počet ověřených témat: {n}.":"Стан бібліотеки порад: {s}. Кількість перевірених тем: {n}.","Změnit jazyk":"Змінити мову","Jazyk se nepodařilo načíst. Zkontrolujte internet.":"Не вдалося завантажити мову. Перевірте інтернет.","Jazyk změněn: {name}":"Мову змінено: {name}","Vyberte jazyk aplikace. Ověřené rady jsou ve všech jazycích stejné.":"Оберіть мову застосунку. Перевірені поради однакові всіма мовами.","Rady se týkají života v Česku – telefonní čísla a instituce jsou české.":"Поради стосуються життя в Чехії — телефонні номери та установи чеські.","Jste znovu připojeni k internetu.":"Ви знову в мережі.","Jste offline. Parťák ale funguje dál.":"Ви офлайн. DIGI parťák працює й далі.","Běžné":"Звичайний","Velké":"Великий","Největší":"Найбільший","Domů":"Головна","Vase zasilka nemohla byt dorucena. Pro opetovne doruceni uhradte poplatek 32 Kc ihned na www.posta-doruceni-cz.top":"Вашу посилку не вдалося доставити. Для повторної доставки терміново сплатіть збір 32 CZK на www.poshta-dostavka-cz.top","Pozor, jde o informaci mimo aplikaci. Není z ověřené knihovny DIGI parťáka, připravila ji umělá inteligence a může obsahovat chybu. Informaci si prosím ověřte.":"Увага, це інформація поза застосунком. Вона не з перевіреної бібліотеки DIGI parťák, її підготував штучний інтелект, і вона може містити помилку. Будь ласка, перевірте інформацію.","Přeskočit na obsah":"Перейти до вмісту","DIGI parťák – domů":"DIGI parťák — головна","Hlavní navigace":"Головна навігація","Návody":"Інструкції","Změnit velikost písma":"Змінити розмір шрифту","Písmo":"Шрифт","Pomoc":"Допомога","Spodní navigace":"Нижня навігація","Podvod?":"Шахрайство?","Obsahuje odkaz":"Містить посилання","Podvodníci posílají odkazy na falešné stránky, kde chtějí údaje z karty nebo hesla.":"Шахраї надсилають посилання на фальшиві сайти, де вимагають дані картки чи паролі.","Zkrácený odkaz":"Скорочене посилання","Zkrácený odkaz skrývá, kam vás ve skutečnosti zavede.":"Скорочене посилання приховує, куди насправді веде.","Chce údaje z karty, heslo nebo kód":"Вимагає дані картки, пароль або код","Banka, pošta ani úřad po vás tyto údaje ve zprávě nikdy nechtějí.":"Банк, пошта чи установа ніколи не просять ці дані в повідомленні.","Tlačí vás do spěchu":"Квапить вас","Spěch a strach jsou hlavní zbraně podvodníků. Skutečné instituce vám dají čas.":"Поспіх і страх — головна зброя шахраїв. Справжні установи дають вам час.","Chce, abyste něco zaplatili":"Хоче, щоб ви щось оплатили","Podvodníci často chtějí „poplatek“, doplatek nebo úhradu. Je to záminka, jak získat vaše peníze nebo údaje z karty.":"Шахраї часто вимагають «збір», доплату чи оплату. Це привід, щоб отримати ваші гроші або дані картки.","Tváří se jako doručení balíku":"Видає себе за доставку посилки","Falešné zprávy o balících jsou jedním z nejčastějších podvodů.":"Фальшиві повідомлення про посилки — одне з найпоширеніших шахрайств.","Vydává se za banku, úřad nebo firmu":"Видає себе за банк, установу чи фірму","Podvodníci se rádi vydávají za důvěryhodné instituce. Ověřte si to sami na oficiálním čísle.":"Шахраї охоче видають себе за надійні установи. Перевірте самі за офіційним номером.","Žádá převod peněz":"Вимагає переказ грошей","Žádný skutečný bankéř ani policista vás nežádá o převod na „bezpečný účet“.":"Жоден справжній банкір чи поліцейський не просить переказати гроші на «безпечний рахунок».","Slibuje výhru nebo dárek":"Обіцяє виграш або подарунок","Pokud jste se soutěže neúčastnili, nemůžete nic vyhrát.":"Якщо ви не брали участі в конкурсі, ви нічого не могли виграти.","Vydává se za někoho z rodiny":"Видає себе за члена родини","Častý trik „Ahoj mami, mám nové číslo“. Zavolejte blízkému na jeho staré číslo.":"Поширений трюк «Привіт, мамо, у мене новий номер». Зателефонуйте рідному на його старий номер.","Žádá o peníze":"Просить гроші","Kdykoli vás zpráva žádá o peníze, ověřte si odesílatele jinou cestou – nejlépe telefonátem na známé číslo.":"Коли повідомлення просить гроші, перевірте відправника іншим шляхом — найкраще дзвінком на відомий номер.","Chce, abyste si něco nainstalovali":"Хоче, щоб ви щось встановили","Aplikace pro vzdálený přístup dávají podvodníkovi kontrolu nad vaším zařízením.":"Програми віддаленого доступу дають шахраєві контроль над вашим пристроєм.","Slibuje rychlý zisk":"Обіцяє швидкий прибуток","Zaručené a vysoké výnosy neexistují. Je to typický investiční podvod.":"Гарантованих високих прибутків не буває. Це типове інвестиційне шахрайство.","Zahraniční telefonní číslo":"Іноземний номер телефону","Zpráva přišla nebo odkazuje na číslo mimo Česko (předvolba jiná než +420).":"Повідомлення надійшло з номера поза Чехією або посилається на нього (код країни не +420).","Česká pošta":"Чеська пошта (Česká pošta)","Policie ČR":"Поліція Чехії (Policie ČR)","Česká bankovní asociace":"Чеська банківська асоціація","NÚKIB – Národní úřad pro kybernetickou a informační bezpečnost":"NÚKIB — Національне управління кібер- та інформаційної безпеки Чехії","Česká národní banka":"Чеський національний банк","Česká obchodní inspekce":"Чеська торгова інспекція","Nápověda Android (Google)":"Довідка Android (Google)","Podpora Apple":"Підтримка Apple","Nápověda WhatsApp":"Довідка WhatsApp","Nápověda Facebooku":"Довідка Facebook","Nápověda Seznam.cz":"Довідка Seznam.cz","Nápověda YouTube":"Довідка YouTube","Manipulátoři.cz":"Manipulátoři.cz (чеська перевірка фактів)","Demagog.cz":"Demagog.cz (чеська перевірка фактів)","Úřad pro ochranu osobních údajů":"Управління із захисту персональних даних Чехії","IDOS – jízdní řády":"IDOS — чеські розклади руху","Mapy.com":"Mapy.com","SÚKL – eRecept":"SÚKL — eRecept (електронний рецепт)","Portál občana":"Портал громадянина (Portál občana)","Integrovaný záchranný systém – tísňová čísla":"Інтегрована рятувальна система — екстрені номери","Život 90 – Senior telefon":"Život 90 — Senior telefon","Elpida – Linka seniorů":"Elpida — лінія для літніх людей","Nápověda Android (Google), Podpora Apple":"Довідка Android (Google), Підтримка Apple","Policie ČR, NÚKIB":"Поліція Чехії, NÚKIB","Česká bankovní asociace, Policie ČR":"Чеська банківська асоціація, Поліція Чехії","SÚKL":"SÚKL","Koncept 11/2026 – před spuštěním nechat zkontrolovat odborníkem":"Чернетка 11/2026 — перед запуском має перевірити фахівець"},"kb":{"sms-balik":["Мені прийшла SMS про посилку, і я маю доплатити збір","Такі повідомлення дуже часто є шахрайством. Шахраї хочуть, щоб ви за посиланням ввели дані платіжної картки.",["Не натискайте посилання в повідомленні й нічого не оплачуйте.","Якщо ви справді чекаєте посилку, перевірте це самі – на офіційному сайті перевізника або телефоном за номером з його сайту.","Видаліть повідомлення. Можна також позначити його як спам.","Якщо ви вже натиснули посилання й ввели картку, негайно телефонуйте у свій банк."],"Служби доставки не просять дані картки через посилання в SMS."],"banka-vola":["Мені телефонує хтось із банку й хоче, щоб я переказав гроші","Покладіть слухавку. Банк ніколи не попросить переказати гроші на «безпечний рахунок» і ніколи не вимагатиме PIN, пароль чи код з SMS.",["Негайно завершіть розмову. Не потрібно бути ввічливими.","Нічого не встановлюйте й нікому не повідомляйте жодних кодів.","Самі зателефонуйте у свій банк – за номером на звороті платіжної картки або з офіційного сайту банку.","Якщо ви вже надіслали гроші чи повідомили дані, одразу скажіть про це банку й телефонуйте в чеську поліцію за номером 158."],"Шахраї вміють підробити навіть справжній номер банку чи поліції. На екрані може бути «правильний» номер – і все одно це може бути шахрайство."],"uz-jsem-zadal":["Я вже натиснув/натиснула посилання або ввів/ввела дані картки","Не бійтеся, діяти ще можна. Що швидше ви зателефонуєте в банк, то більше шансів урятувати гроші.",["Негайно зателефонуйте у свій банк за номером на звороті картки або з офіційного сайту банку. Попросіть заблокувати картку.","Якщо ви дали комусь доступ до телефона чи комп'ютера, вимкніть інтернет (Wi-Fi і мобільні дані).","Змініть пароль до інтернет-банкінгу та e-mail – найкраще з допомогою близької людини.","Повідомте про шахрайство чеську поліцію за номером 158.","Не соромтеся. Шахраї – професіонали, вони обманюють і молодих, і досвідчених людей."],""],"falesny-policista":["Мені телефонує «поліцейський» і хоче, щоб я дав/дала йому гроші","Справжня поліція ніколи не вимагатиме від вас грошей, готівки чи переказу на рахунок. Це шахрайство.",["Покладіть слухавку й нікому нічого не передавайте.","Самі зателефонуйте на 158 і розкажіть, що сталося.","Якщо хтось стоїть під дверима, не відчиняйте й телефонуйте на 158."],""],"vnoucatko":["Мені пише «онук» або «донька» з нового номера й просить гроші","Це поширене шахрайство. Перш ніж щось надіслати, переконайтеся, що вам справді пише ваш рідний.",["Не надсилайте гроші чи коди.","Зателефонуйте рідному на його СТАРИЙ, відомий номер або запитайте іншого члена родини.","Можна поставити запитання, відповідь на яке знає лише він (наприклад, кличку вашого собаки).","Якщо з'ясується, що це шахрай, заблокуйте номер."],""],"vzdalena-plocha":["Хтось хоче, щоб я встановив/встановила програму (AnyDesk, TeamViewer)","Ніколи не встановлюйте програму на прохання людини, яка сама вам зателефонувала чи написала. Вона отримала б доступ до вашого телефона й банкінгу.",["Завершіть дзвінок або розмову.","Нічого не встановлюйте. Якщо вже встановили, вимкніть інтернет і видаліть програму.","Зателефонуйте в банк за офіційним номером і розкажіть, що сталося."],"Банки, Microsoft чи оператори ніколи самі не телефонують через «віруси в комп'ютері»."],"investice":["Мені пропонують інвестицію, криптовалюту або швидкий прибуток","Обіцянка високого «гарантованого» прибутку – типова ознака шахрайства. Часто для цього зловживають фото відомих людей.",["Нікому не надсилайте гроші чи документи.","Не встановлюйте програм, які радить «консультант».","На сайті Чеського національного банку можна перевірити, чи має фірма дозвіл.","Про інвестиції порадьтеся особисто у своєму банку або з кимось близьким."],"DIGI parťák не дає інвестиційних порад – лише допомагає розпізнати шахрайство."],"vyhra":["Нібито я щось виграв/виграла й маю сплатити збір","Якщо ви не брали участі в конкурсі, ви нічого не виграли. Справжній виграш ніколи не вимагає оплати чи даних картки.",["Не натискайте посилання й нічого не оплачуйте.","Видаліть повідомлення.","Якщо ви ввели картку, телефонуйте в банк."],""],"jak-poznat-podvod":["Як розпізнати шахрайське повідомлення чи e-mail?","Шахрайські повідомлення зазвичай мають кілька спільних ознак. Досить помітити одну з них і насторожитися.",["Поспіх і страх: «негайно», «протягом 24 годин», «рахунок буде заблоковано».","Посилання, за яким треба щось заповнити чи оплатити.","Прохання надати номер картки, PIN, пароль чи код з SMS.","Невідомий відправник, іноземний номер або дивна адреса.","Якщо не впевнені, вставте повідомлення в інструмент «Це шахрайство?» або запитайте близьку людину."],""],"heslo":["Як створити безпечний пароль?","Найкраще – довгий пароль з кількох слів, який ви легко запам'ятаєте, але ніхто інший не вгадає.",["З'єднайте 3–4 слова, що не пов'язані між собою, наприклад «Drozd-Bulka-Sad-27» (але цей не використовуйте, він публічний).","Для кожного облікового запису використовуйте інший пароль – особливо для e-mail і банку.","Паролі можна записати в зошит, який залишиться вдома. Ніколи їх не фотографуйте й не надсилайте.","Де можливо, увімкніть двоетапну перевірку (код в SMS або в застосунку)."],"Ніколи нікому не повідомляйте свій пароль – ні банку, ні «технікові». Навіть DIGI parťák."],"nakup-online":["Як безпечно купувати в інтернеті?","Купуйте у відомих інтернет-магазинах, а щодо невідомих спершу перевірте, хто за ними стоїть.",["Адресу магазину введіть самі, не натискайте посилання з реклами та повідомлень.","Перегляньте контакти, ідентифікаційний номер (IČO) і адресу продавця та відгуки інших людей.","Будьте обережні, коли ціна підозріло низька.","У невідомого продавця обирайте оплату при отриманні.","На сайтах оголошень ніколи не надсилайте код з SMS і не вводьте картку за посиланням від «покупця»."],""],"laska-online":["Я познайомився/познайомилася з кимось в інтернеті, і ця людина просить гроші","Якщо гроші просить людина, з якою ви ніколи не зустрічалися особисто, це з високою ймовірністю шахрайство.",["Не надсилайте гроші, подарунки чи коди.","Поговоріть про це з кимось близьким.","Якщо ви вже надіслали гроші, телефонуйте в банк і в чеську поліцію (158)."],""],"pismo":["Як збільшити шрифт у телефоні?","Шрифт збільшують у Налаштуваннях телефона. Назви пунктів можуть трохи відрізнятися залежно від виробника.",["Android: відкрийте Налаштування → Дисплей (або Спеціальні можливості) → Розмір шрифту.","iPhone: відкрийте Параметри → Дисплей і яскравість → Розмір тексту.","Посуньте повзунок праворуч, доки текст не стане зручним для читання.","У DIGI parťák шрифт збільшують кнопкою «Шрифт» угорі."],""],"whatsapp-fotka":["Як надіслати фото через WhatsApp?","Фото надсилають за кілька кроків прямо з розмови з потрібною людиною.",["Відкрийте WhatsApp і торкніться імені людини.","Унизу торкніться значка скріпки або «+».","Оберіть «Галерея» (Android) або «Фото» (iPhone).","Торкніться фото, а потім зеленої стрілки, щоб надіслати."],""],"whatsapp-video":["Як зателефонувати з відео через WhatsApp?","Відеодзвінок починають одним дотиком у розмові з потрібною людиною.",["Відкрийте WhatsApp і торкніться імені людини.","Угорі праворуч торкніться значка камери.","Зачекайте, доки інша людина відповість.","Дзвінок завершують червоною кнопкою."],""],"wifi":["Як підключитися до Wi-Fi?","До домашнього Wi-Fi підключаються в Налаштуваннях. Потрібні назва мережі й пароль – зазвичай вони на наліпці роутера.",["Відкрийте Налаштування → Wi-Fi (на Android іноді Підключення → Wi-Fi).","Увімкніть Wi-Fi, якщо його вимкнено.","Торкніться назви своєї мережі.","Введіть пароль з наліпки на роутері й підтвердьте."],"У публічному Wi-Fi (кав'ярня, вокзал) краще не користуйтеся інтернет-банкінгом."],"aktualizace":["Чи оновлювати телефон?","Так, оновлення з Налаштувань телефона важливі – вони виправляють помилки безпеки.",["Запускайте оновлення лише з Налаштувань телефона або з Google Play / App Store.","Перед оновленням зарядіть телефон і підключіться до Wi-Fi.","Якщо до «оновлення» закликає посилання в SMS чи e-mail, це шахрайство."],""],"screenshot":["Як зробити знімок екрана (скриншот)?","Знімок екрана – це «фото» того, що зараз на дисплеї. Він знадобиться, наприклад, щоб перевірити підозрілу SMS у DIGI parťák.",["Android: одночасно натисніть кнопку живлення й кнопку зменшення гучності (нижню) і одразу відпустіть.","iPhone без кнопки «Додому»: одночасно натисніть бічну кнопку й кнопку збільшення гучності (верхню).","iPhone з кнопкою «Додому» (кругла внизу): одночасно натисніть кнопку «Додому» й бічну (або верхню) кнопку.","Екран коротко блимне. Знімок знайдете в Галереї (Android) або у Фото (iPhone)."],"На деяких телефонах Android поєднання кнопок відрізняється залежно від виробника."],"plocha":["Як додати DIGI parťák на головний екран телефона?","DIGI parťák можна додати на головний екран як звичайний застосунок. Тоді ви відкриватимете його одним дотиком.",["Android (Chrome): торкніться трьох крапок угорі праворуч → «Додати на головний екран» або «Установити застосунок».","iPhone (Safari): торкніться значка «Поширити» внизу (квадрат зі стрілкою) → «На початковий екран».","Підтвердьте кнопкою «Додати»."],""],"facebook":["Що таке Facebook і як почати ним користуватися?","Facebook – це соціальна мережа, місце в інтернеті, де люди діляться фото й новинами та надсилають одне одному повідомлення (через застосунок Messenger). Користування безкоштовне.",["Завантажте застосунок Facebook з Google Play (Android) або App Store (iPhone) або самі введіть у браузері facebook.com.","Новий обліковий запис: торкніться «Створити новий обліковий запис» і вкажіть ім'я, дату народження та e-mail або телефон. Оберіть пароль.","Вхід: введіть e-mail або телефон і пароль та торкніться «Увійти».","У налаштуваннях конфіденційності оберіть, щоб ваші дописи бачили лише «Друзі».","Приймайте запити на дружбу лише від людей, яких справді знаєте."],"На Facebook трапляються фальшиві профілі та реклама «гарантованих заробітків» з відомими людьми. Якщо вас просять про гроші, перевірте це телефоном."],"whatsapp-zacit":["Що таке WhatsApp і як його встановити?","WhatsApp – застосунок для повідомлень, фото й дзвінків (зокрема з відео) через інтернет. Через Wi-Fi він безкоштовний, навіть за кордон. Використовує ваш номер телефона.",["Відкрийте Google Play (Android) або App Store (iPhone) і знайдіть «WhatsApp Messenger».","Перевірте, що розробник – «WhatsApp LLC», і торкніться «Установити» («Завантажити»).","Відкрийте WhatsApp, прийміть умови й введіть свій номер телефона.","Вам прийде SMS з кодом – вводьте його лише безпосередньо у WhatsApp.","Напишіть своє ім'я. Ваші контакти, які мають WhatsApp, з'являться самі."],"Ніколи нікому не надсилайте код підтвердження WhatsApp – навіть «другові», який його просить. Так шахраї крадуть облікові записи."],"email":["Як створити e-mail і надіслати лист із вкладенням?","E-mail – це електронна пошта. У Чехії найпоширеніші пошта Seznam.cz і Gmail від Google. Обидві безкоштовні.",["Створення: на сайті seznam.cz торкніться «E-mail» і «Zaregistrovat se» або створіть обліковий запис Google (Gmail) – на Android він зазвичай уже є.","Придумайте адресу (наприклад, olena.koval@seznam.cz) і безпечний пароль. Запишіть обидва.","Надсилання: торкніться «Написати», у полі «Кому» введіть адресу, напишіть тему й текст.","Вкладення (фото): торкніться значка скріпки й оберіть фото.","Торкніться «Надіслати» (стрілка)."],"Листи, які просять пароль, оплату чи перехід за посиланням, часто є шахрайством. Якщо не впевнені, вставте їх у «Це шахрайство?»."],"youtube":["Що таке YouTube і як шукати там відео?","YouTube – сайт і застосунок з відео: пісні, передачі, рецепти, інструкції. Він безкоштовний, лише іноді показує рекламу.",["Відкрийте застосунок YouTube (зазвичай уже є в телефоні) або введіть у браузері youtube.com.","Торкніться лупи вгорі й напишіть, що шукаєте (наприклад, «Софія Ротару» або «рецепт вареників»).","Торкніться відео. Рекламу можна пропустити через кілька секунд кнопкою «Пропустити».","Щоб відео заповнило весь екран, поверніть телефон горизонтально."],"Реклама швидкого збагачення чи чудодійних ліків часто є шахрайством, навіть якщо в ній з'являються відомі люди."],"aplikace-instalace":["Як безпечно встановити застосунок?","Завантажуйте застосунки лише з офіційного магазину: Google Play на Android, App Store на iPhone. Більшість застосунків безкоштовні.",["Відкрийте Google Play (кольоровий трикутник) або App Store (синя «A»).","Угорі торкніться пошуку й напишіть назву застосунку.","Перевірте назву розробника (наприклад, для банківського застосунку – ваш банк) і оцінки.","Торкніться «Установити» (Android) або «Завантажити» (iPhone) і зачекайте.","Видалення: утримуйте палець на значку застосунку й оберіть «Видалити» / «Вилучити застосунок»."],"Ніколи не встановлюйте застосунок за вказівкою невідомого абонента чи з посилання в SMS."],"zapomenute-heslo":["Я забув/забула пароль – що тепер?","Забутий пароль майже завжди можна відновити. Сервіс надішле код на телефон чи e-mail, і ви встановите новий пароль.",["На сторінці входу торкніться «Забули пароль?».","Введіть свій e-mail або телефон. Прийде SMS або лист із кодом чи посиланням.","Вводьте код лише на тій сторінці, де ви самі почали відновлення.","Придумайте новий пароль і запишіть його в зошит, що залишиться вдома.","Щодо інтернет-банкінгу телефонуйте в банк за номером на звороті картки."],"Якщо вам прийшов код для відновлення пароля, якого ви не запитували, нікому його не надсилайте – можливо, хтось намагається зайти у ваш обліковий запис."],"baterie":["Телефон швидко розряджається – що робити?","Найбільше енергії споживають яскравий екран, навігація, відео й застосунки у фоновому режимі. Кілька змін помітно подовжать роботу.",["Зменште яскравість екрана (потягніть панель згори й посуньте повзунок із сонечком).","Увімкніть режим енергозбереження: Android – Налаштування → Батарея → Енергозбереження; iPhone – Параметри → Акумулятор → Режим низького живлення.","Закрийте застосунки, якими не користуєтеся, і вимкніть геолокацію (GPS), коли вона не потрібна.","Заряджайте оригінальним або якісним зарядним пристроєм. Не обов'язково чекати, доки телефон повністю розрядиться.","Якщо телефону кілька років і він усе одно швидко розряджається, може допомогти заміна батареї в сервісі."],""],"pamet":["Телефон повідомляє, що пам'ять заповнена – як звільнити місце?","Найчастіше місце займають відео, фото й файли з WhatsApp. Перш ніж видаляти, зробіть їх резервну копію.",["Подивіться, що займає місце: Android – Налаштування → Пам'ять (або Обслуговування пристрою); iPhone – Параметри → Загальні → Сховище iPhone.","Збережіть копію фото (Google Фото або iCloud), а потім видаліть великі відео.","У WhatsApp: Налаштування → Пам'ять і дані → Керування пам'яттю – видаліть великі файли й переслані відео.","Видаліть застосунки, якими не користуєтеся.","Наостанок очистьте кошик у Фото («Нещодавно видалені»)."],""],"pomaly-telefon":["Телефон повільний або зависає","Найчастіше допомагає звичайне перезавантаження. Телефон так «прибирає» пам'ять.",["Перезавантажте телефон: утримуйте кнопку живлення й оберіть «Перезапустити» (на iPhone – вимкнути й знову увімкнути).","Якщо телефон зовсім не реагує, утримуйте кнопку живлення довше (близько 10–15 секунд).","Установіть оновлення системи й застосунків.","Звільніть пам'ять – повна пам'ять сповільнює телефон.","Якщо нічого не допомагає, порадьтеся в магазині чи сервісі свого оператора."],""],"hlasitost":["Я не чую дзвінка – як зробити телефон гучнішим?","Гучність дзвінка налаштовують кнопками збоку телефона або в Налаштуваннях. Перевірте також, чи телефон не в беззвучному режимі.",["Натисніть верхню кнопку гучності збоку телефона, коли не відтворюється відео.","Android: Налаштування → Звуки та вібрація → Гучність → посуньте «Мелодія дзвінка» праворуч.","iPhone: Параметри → Звуки і тактильні сигнали → посуньте повзунок «Дзвінок і сповіщення». Збоку перевірте перемикач беззвучного режиму (помаранчевий = тиша).","Вимкніть режим «Не турбувати» (значок місяця на верхній панелі).","Увімкніть і вібрацію, щоб відчувати дзвінок у кишені."],""],"blokovani":["Як заблокувати набридливий номер?","Номер, що вам набридає, можна заблокувати в телефоні. Тоді з нього ніхто не зателефонує й не напише.",["Android: відкрийте застосунок Телефон → Останні, утримуйте палець на номері й оберіть «Заблокувати» (або «Повідомити про спам»).","iPhone: відкрийте Телефон → Останні, торкніться «i» біля номера, а потім «Заблокувати абонента».","Для SMS: відкрийте повідомлення, торкніться номера вгорі й оберіть «Заблокувати».","Невідомі номери можна не брати. Хто вас потребує, залишить повідомлення або напише."],"Якщо абонент стверджує, що він з банку чи поліції, покладіть слухавку й самі зателефонуйте за офіційним номером."],"kontakt":["Як зберегти номер телефона в контактах?","Номер легко зберегти із застосунку Телефон або Контакти. Тоді під час дзвінка ви бачитимете ім'я замість номера.",["Відкрийте застосунок Телефон → Останні й торкніться номера, який хочете зберегти.","Оберіть «Створити новий контакт» або «Додати контакт» (на iPhone «i» → Створити новий контакт).","Напишіть ім'я та прізвище, за бажання додайте фото.","Торкніться «Зберегти» («Готово»).","Новий номер можна також додати в застосунку Контакти кнопкою «+»."],""],"nouzove-info":["Як налаштувати в телефоні медичні дані та екстрений контакт?","У телефоні можна зберегти медичні дані й екстрений контакт. Рятувальники побачать їх навіть на заблокованому телефоні.",["iPhone: відкрийте застосунок «Здоров'я» → ваше фото вгорі праворуч → «Медична картка» → «Змінити». Заповніть дані й увімкніть «Показувати на заблокованому екрані».","Android: Налаштування → Безпека та екстрені ситуації (або Екстрена інформація). Точна назва залежить від виробника.","Додайте екстрений контакт – когось близького.","Вкажіть важливі хвороби, алергії та ліки, які ви приймаєте."],""],"ztraceny-telefon":["Я загубив/загубила телефон – як його знайти?","Телефон можна знайти, заблокувати або змусити дзвонити дистанційно з комп'ютера чи телефона близької людини.",["Android: на іншому пристрої відкрийте сторінку android.com/find і увійдіть у свій обліковий запис Google.","iPhone: відкрийте сторінку icloud.com/find і увійдіть зі своїм Apple ID (або скористайтеся застосунком «Локатор» на іншому пристрої Apple).","Телефон можна змусити дзвонити, показати на карті або заблокувати.","У разі крадіжки телефонуйте своєму операторові (блокування SIM), у банк (якщо в телефоні є банкінг) і в чеську поліцію за номером 158."],""],"zaloha-fotek":["Як зробити резервну копію фото, щоб їх не втратити?","Фото з резервною копією автоматично зберігаються й поза телефоном. Якщо ви загубите чи розіб'єте телефон, фото залишаться.",["Android: відкрийте застосунок Google Фото → ваш значок угорі праворуч → увімкніть «Резервне копіювання».","iPhone: Параметри → ваше ім'я вгорі → iCloud → Фото → увімкніть «Синхронізувати цей iPhone».","Копіювання найкраще працює через Wi-Fi і під час заряджання.","Безкоштовно доступне лише обмежене місце. Коли воно закінчиться, сервіс запропонує платне розширення – купувати не обов'язково, можна видалити непотрібне."],""],"mobilni-data":["Що таке мобільні дані й коли їх вмикати?","Мобільні дані – це інтернет від вашого оператора. Вони працюють і надворі, де немає Wi-Fi. Скільки даних у вас є, залежить від тарифу.",["Увімкнення: потягніть пальцем панель від верхнього краю й торкніться значка «Мобільні дані» (дві стрілки).","Удома й у рідних краще користуйтеся Wi-Fi – він не витрачає ваші дані.","За кордоном поза ЄС вимкніть дані або роумінг, щоб не отримати великий рахунок. У ЄС ви платите як удома.","Скільки даних залишилося, дізнаєтеся в застосунку свого оператора."],""],"qr-kod":["Як відсканувати QR-код?","QR-код – це квадрат із крапок, що містить посилання або платіжні дані. Його зчитують камерою телефона.",["Відкрийте Камеру й наведіть її на QR-код (нічого не фотографуйте).","З'явиться посилання – торкніться його.","QR-платіж (наприклад, на квитанції): відкрийте застосунок свого банку й оберіть «Оплата QR-кодом». Дані заповняться самі – перевірте суму й отримувача."],"QR-коди в e-mail, SMS або наклеєні на паркувальних автоматах можуть вести на шахрайські сайти. Платіть лише в застосунку свого банку."],"pin-karty":["Як змінити PIN картки?","PIN картки можна змінити в застосунку свого банку, в інтернет-банкінгу, у відділенні або в деяких банкоматах вашого банку.",["Відкрийте застосунок банку й шукайте біля картки «Змінити PIN» або «Показати PIN».","Без застосунку прийдіть у відділення банку з документом, що посвідчує особу.","Новий PIN обирайте так, щоб це не була дата народження чи 1234.","Не записуйте PIN поруч із карткою чи в телефоні."],"Банк ніколи не просить ваш PIN – ні телефоном, ні в SMS, ні e-mail. Хто його просить – шахрай."],"internetove-bankovnictvi":["Як безпечно почати користуватися інтернет-банкінгом?","Інтернет-банкінг вам підключить ваш банк – найнадійніше особисто у відділенні, де одразу допоможуть з налаштуванням.",["Прийдіть у відділення й попросіть інтернет- і мобільний банкінг. Скажіть, що ви лише починаєте.","Застосунок банку завантажуйте лише з Google Play або App Store (видавцем має бути ваш банк).","Входьте в банкінг лише через цей застосунок або адресу, яку введете самі. Ніколи через посилання з повідомлення.","Рахунок оплачуйте через «Оплата QR-кодом» або «Новий платіж». Перед підтвердженням перевірте номер рахунку й суму."],"Нікому не повідомляйте дані для входу та коди підтвердження. Банк ніколи не попросить переказати гроші на «безпечний рахунок»."],"platba-telefonem":["Як платити телефоном замість картки?","Платіжну картку можна додати в телефон і платити, прикладаючи телефон до термінала, так само як карткою.",["Відкрийте застосунок банку й шукайте біля картки «Додати в Google Wallet» або «Додати в Apple Wallet».","Підтвердьте додавання за інструкцією банку.","Під час оплати розблокуйте телефон і прикладіть його до термінала.","Захистіть телефон кодом або відбитком пальця."],""],"hoax":["Як розпізнати фейк і неправдиву новину?","Фейк (hoax) – це тривожне або вигадане повідомлення, що поширюється пересиланням. Воно часто лякає, обурює чи обіцяє дива.",["Насторожіться, коли повідомлення закликає «перешли всім» або дуже лякає й обурює.","Шукайте джерело: хто це написав і де опубліковано? Серйозні новини мають автора й дату.","Перевірте це в надійному медіа або на сайтах перевірки фактів (у Чехії Manipulátoři.cz і Demagog.cz).","Якщо не впевнені, не пересилайте повідомлення."],""],"cookies":["Що робити з панеллю «cookies» на сайті?","Cookies – це маленькі файли, якими сайт запам'ятовує, що ви робите. Панель питає, чи може він стежити за вашою поведінкою для реклами.",["Спокійно оберіть «Відхилити все» або «Лише необхідні». Сайт працюватиме далі.","Якщо такої кнопки немає, торкніться «Налаштування» й залиште ввімкненими лише «Необхідні».","Не потрібно щоразу займатися панеллю – сайт запам'ятає ваш вибір."],""],"vir-hlaska":["На сайті вискочило, що в моєму телефоні вірус","Повідомлення на сайтах на кшталт «Ваш телефон заражено!» майже завжди є шахрайством. Вони хочуть налякати вас, щоб ви щось установили чи оплатили.",["Нічого не натискайте у вікні й не телефонуйте за вказаним номером.","Закрийте вкладку або весь браузер. За потреби перезавантажте телефон.","Нічого не встановлюйте й нічого не оплачуйте.","Якщо ви вже щось установили чи ввели картку, телефонуйте в банк і попросіть про допомогу близьку людину."],""],"mapy":["Як знайти дорогу й транспортне сполучення в телефоні?","Дорогу й сполучення можна знайти в застосунках Mapy.com (раніше Mapy.cz) або Google Карти. Чеські розклади руху – на сайті IDOS.",["Відкрийте Mapy.com або Google Карти й у пошуку напишіть, куди хочете дістатися.","Торкніться «Маршрут» і оберіть, чи йдете пішки, їдете авто чи громадським транспортом.","Автобусні й залізничні сполучення знайдете на сайті idos.cz – вкажіть звідки, куди й коли.","Квиток на потяг купите в застосунку Můj vlak (Чеські залізниці) або в касі. Про знижки для літніх людей запитайте в касі."],""],"objednat-lekar":["Як записатися до лікаря через інтернет?","Багато лікарень і кабінетів пропонують запис через інтернет або e-mail. Але кожен використовує свою систему, тому спершу запитайте в кабінеті.",["Запитайте медсестру, чи можна записатися онлайн і за якою адресою.","Попросіть записати адресу чи застосунок на папері й введіть її в браузері самі.","Оберіть час і підтвердьте його. Зазвичай прийде підтвердження e-mail або SMS.","Якщо онлайн-запис вам не підходить, дзвінок у кабінет – теж нормально."],"На запитання про здоров'я та ліки відповість лікар або фармацевт."],"erecept":["Як працює електронний рецепт (eRecept)?","eRecept – це електронний рецепт. Лікар надішле його в SMS чи e-mail або роздрукує.",["Зачекайте на SMS або лист від лікаря з кодом рецепта.","В аптеці покажіть повідомлення з кодом (або роздрукований папір).","Фармацевт зчитає код і видасть вам ліки.","Код можна надіслати й близькій людині, яка забере ліки замість вас."],"На запитання про ліки, дозування та здоров'я відповідає лікар або фармацевт, а не DIGI parťák."],"identita":["Як вирішувати справи з чеськими установами через інтернет?","Багато справ із чеськими установами можна вирішити на Порталі громадянина (Portál občana). Входять, наприклад, через банківську ідентичність – так само, як в інтернет-банкінг.",["Адресу Порталу громадянина введіть у браузері самі: obcan.portal.gov.cz.","Оберіть вхід через свій банк (банківська ідентичність) або інший запропонований спосіб.","Якщо не впевнені, попросіть про допомогу близьку людину або працівника Czech POINT на пошті чи в установі."],"Не користуйтеся посиланнями на «установу» з SMS чи e-mail – адресу завжди вводьте самі."],"cisla":["Які телефонні номери важливі?","Ось найважливіші номери. Торкніться будь-якого, щоб одразу зателефонувати.",[],""],"samota":["Мені сумно, і я почуваюся самотньо","Мені шкода. Такі почуття цілком нормальні, і ви не мусите бути з ними на самоті. На цих безкоштовних лініях вас охоче вислухають (чеською).",[],""],"krize":["Мені справді погано, і я не знаю, що робити","Мені дуже шкода, що ви так почуваєтеся. Будь ласка, поговоріть із кимось просто зараз. Ви важливі.",["Зателефонуйте на Лінію першої психологічної допомоги 116 123 – безкоштовно й цілодобово (чеською).","Якщо ви в небезпеці, телефонуйте 112 (можна й англійською) або 155.","Можна також зателефонувати комусь близькому й попросити прийти."],""],"zdravi-nouze":["Проблеми зі здоров'ям – викличте допомогу","Це може бути серйозно. Будь ласка, негайно телефонуйте в швидку допомогу 155 або на екстрену лінію 112.",["Зателефонуйте 155 або 112.","Скажіть, де ви й що сталося.","Якщо можливо, відчиніть двері й зателефонуйте сусідові чи близькій людині."],""],"mimo-zdravi":["Запитання про здоров'я та ліки","На запитання про здоров'я та ліки безпечно відповість лише лікар або фармацевт. Я не хочу дати неточну пораду.",["Зателефонуйте своєму сімейному лікареві.","Запитайте в аптеці – фармацевти охоче порадять безкоштовно.","У разі раптових проблем телефонуйте 155."],""],"mimo-finance":["Фінансові та юридичні поради","Фінансових і юридичних порад я не даю – можу ненавмисно зашкодити. Будь ласка, зверніться до фахівця.",["Про гроші порадьтеся особисто у своєму банку.","З юридичними питаннями допомагають безкоштовні консультації, наприклад через Senior telefon (чеською).","Якщо вас тиснуть і квапять підписати договір, нічого не підписуйте."],""],"pozdrav":["Привітання","Добрий день, радий вас бачити! Я – DIGI parťák. Допоможу з телефоном, інтернетом і безпекою онлайн. Про що хочете запитати?",[],""],"dekuji":["Подяка","Будь ласка! Я тут, щойно знадоблюся. Немає дурних запитань.",[],""],"kdo-jsi":["Хто такий DIGI parťák?","Я – DIGI parťák, цифровий помічник, а не людина. Спершу відповідаю з бібліотеки перевірених порад. Якщо відповіді там немає, спробую допомогти за допомогою штучного інтелекту й завжди нагадаю, що це треба перевірити.",["Допоможу з телефоном і застосунками.","Допоможу розпізнати шахрайські повідомлення та дзвінки.","Покажу, куди телефонувати по допомогу."],""]},"guides":{"pismo":["Збільшити шрифт у телефоні","Більший шрифт легше читати, і він береже очі. Нічого не зіпсується – повернути можна будь-коли.",[["Відкрийте Налаштування","Знайдіть на екрані значок шестерні з написом «Налаштування» й торкніться його. ||"],["Знайдіть пункт дисплея","Android: торкніться «Дисплей» (на деяких телефонах «Спеціальні можливості»). iPhone: торкніться «Дисплей і яскравість».","Пункти можна шукати й лупою вгорі – напишіть «шрифт»."],["Торкніться «Розмір шрифту»","Android: «Розмір шрифту» або «Розмір і стиль шрифту». iPhone: «Розмір тексту». ||"],["Посуньте повзунок праворуч","Що далі праворуч, то більший шрифт. Зразок тексту одразу змінюється, тож ви побачите результат. ||"],["Готово","Поверніться кнопкою «Назад» або закрийте Налаштування. Шрифт залишиться більшим у всьому телефоні. ||"]]],"whatsapp-fotka":["Надіслати фото через WhatsApp","Порадуйте родину. Фото надсилають прямо з розмови з потрібною людиною.",[["Відкрийте WhatsApp","Торкніться зеленого значка з білим телефоном у бульбашці. ||"],["Оберіть людину","У списку розмов торкніться імені того, кому хочете надіслати фото. ||"],["Торкніться скріпки або +","Значок унизу поруч із полем для тексту. На Android це скріпка, на iPhone – знак плюс. ||"],["Оберіть фото","Торкніться «Галерея» (Android) або «Медіатека» (iPhone), а потім фото, яке хочете надіслати. ||"],["Надішліть","Торкніться круглої зеленої кнопки зі стрілкою. Фото вже в дорозі!","Дві сині галочки означають, що інша людина вже переглянула фото."]]],"whatsapp-video":["Відеодзвінок через WhatsApp","Бачтеся з рідними, навіть коли вони далеко. Дзвінок через Wi-Fi нічого не коштує.",[["Відкрийте WhatsApp","Торкніться зеленого значка WhatsApp. ||"],["Оберіть людину","Торкніться імені того, кому хочете зателефонувати. ||"],["Торкніться камери","Угорі праворуч є значок маленької камери. Торкніться його.","Значок слухавки поруч – звичайний дзвінок без відео."],["Зачекайте на відповідь","Коли інша людина відповість, ви побачите одне одного. Тримайте телефон перед обличчям. ||"],["Завершіть дзвінок","Торкніться червоної кнопки зі слухавкою. ||"]]],"podvodna-sms":["Що робити з підозрілою SMS","Шахрайські повідомлення отримують усі. Важливо знати, як діяти.",[["Не поспішайте","Шахраї хочуть, щоб ви діяли негайно. А у вас є час. Глибоко вдихніть. ||"],["Не натискайте посилання","Не торкайтеся посилання в повідомленні й не відповідайте на нього. ||"],["Перевірте інакше","Якщо повідомлення нібито від банку, пошти чи установи, самі зателефонуйте їм за номером з офіційного сайту або з картки. ||"],["Видаліть повідомлення","Утримуйте палець на повідомленні й оберіть «Видалити». Номер можна заблокувати. ||"],["Уже натиснули?","Нічого не станеться, якщо ви нічого не заповнили. Якщо ви ввели картку чи пароль, негайно телефонуйте у свій банк.","Повідомлення можна перевірити в DIGI parťák у розділі «Це шахрайство?»."]]],"screenshot-android":["Знімок екрана на Android","Знімок екрана (скриншот) – це фото того, що зараз на дисплеї. Він знадобиться, наприклад, для перевірки підозрілого повідомлення.",[["Відкрийте те, що хочете зняти","Наприклад, підозрілу SMS. Відкрийте повідомлення так, щоб було видно весь текст і відправника. ||"],["Знайдіть дві кнопки","Збоку телефона є кнопка живлення й кнопки гучності. Знадобляться кнопка живлення й нижня кнопка гучності (тихіше). ||"],["Натисніть обидві одночасно","Одночасно натисніть живлення й «тихіше». Утримуйте лише мить (близько 1 секунди) і відпустіть.","Якщо замість цього з'явиться меню вимкнення, ви відпустили кнопки запізно. Спробуйте ще раз швидше."],["Екран блимне","Ви почуєте звук або побачите коротке блимання й маленький попередній перегляд унизу. Знімок збережено. ||"],["Де знайти знімок","Відкрийте застосунок Галерея або Google Фото. Знімок серед найновіших фото, часто в папці «Знімки екрана». ||"],["Не виходить?","На деяких телефонах (наприклад, Samsung) можна й так: потягніть панель від верхнього краю вниз і торкніться «Знімок екрана». Спосіб залежить від виробника.","Знімок можна завантажити в DIGI parťák у розділі «Це шахрайство?»."]]],"screenshot-iphone":["Знімок екрана на iPhone","Знімок екрана (скриншот) – це фото того, що зараз на дисплеї. Спосіб залежить від того, чи має ваш iPhone круглу кнопку «Додому» під екраном.",[["Відкрийте те, що хочете зняти","Наприклад, підозрілу SMS. Відкрийте повідомлення так, щоб було видно весь текст і відправника. ||"],["iPhone БЕЗ кнопки «Додому»","Новіші iPhone (екран до краю): одночасно натисніть бічну кнопку праворуч і кнопку збільшення гучності ліворуч (верхню). Одразу відпустіть. ||"],["iPhone З кнопкою «Додому»","Старіші iPhone та iPhone SE (кругла кнопка внизу): одночасно натисніть кнопку «Додому» й бічну кнопку праворуч (на найстаріших моделях – кнопку вгорі). ||"],["Екран блимне","Екран на мить побіліє, а ліворуч унизу з'явиться маленький попередній перегляд. Торкатися його не потрібно – знімок збережеться сам.","Якщо замість цього з'явиться повзунок «Вимкнути», ви тримали кнопки задовго. Торкніться «Скасувати» й спробуйте швидше."],["Де знайти знімок","Відкрийте застосунок Фото. Знімок серед найновіших фото, а також в альбомі «Знімки екрана».","Знімок можна завантажити в DIGI parťák у розділі «Це шахрайство?»."]]],"banka-hovor":["Телефонує «банк» – що робити?","Найпоширеніше шахрайство щодо літніх людей. Досить запам'ятати одне правило: покласти слухавку й зателефонувати самому.",[["Покладіть слухавку","Коли хтось із «банку» чи «поліції» телефонує щодо грошей, завершіть розмову. Вибачатися не потрібно. ||"],["Нічого не повідомляйте","Нікому не кажіть PIN, паролі чи коди з SMS. Банк ніколи їх не попросить. ||"],["Зателефонуйте самі","Візьміть платіжну картку й зателефонуйте за номером на її звороті. ||"],["Розкажіть, що сталося","Працівник банку скаже, чи все гаразд із вашим рахунком. ||"]]],"erecept":["Отримати електронний рецепт (eRecept)","Рецепт більше не мусить бути паперовим. Досить коду, який надішле лікар.",[["Зачекайте на повідомлення","Лікар надішле вам SMS або e-mail з кодом рецепта. Може також його роздрукувати. ||"],["Ідіть в аптеку","Можна піти в будь-яку аптеку. ||"],["Покажіть код","Відкрийте повідомлення від лікаря й покажіть його фармацевтові або продиктуйте код. ||"],["Готово","Фармацевт зчитає код і видасть вам ліки.","Код можна переслати близькій людині, яка забере ліки замість вас."]]],"plocha":["DIGI parťák на головному екрані","Додайте помічника на головний екран як застосунок. Тоді відкриватимете його одним дотиком.",[["Відкрийте DIGI parťák у браузері","Android: у Chrome. iPhone: у Safari. ||"],["Відкрийте меню","Android: торкніться трьох крапок угорі праворуч. iPhone: торкніться значка «Поширити» внизу (квадрат зі стрілкою вгору). ||"],["Додати на головний екран","Оберіть «Додати на головний екран» або «Установити застосунок». ||"],["Підтвердьте","Торкніться «Додати». На екрані з'явиться значок з усміхненою бульбашкою. ||"]]]},"phones":{"112":["Екстрена лінія","Будь-яка загроза життю, здоров'ю чи майну. Працює навіть без коштів на рахунку, можна й англійською."],"150":["Пожежна служба","Пожежа, витік газу, технічна допомога."],"155":["Швидка допомога","Раптові проблеми зі здоров'ям, травма, непритомність."],"158":["Поліція Чехії","Шахрайство, крадіжка, погрози, підозріла людина під дверима."],"senior":["Senior telefon (Život 90)","Безкоштовна лінія для літніх людей та їхніх рідних. Цілодобово, чеською."],"elpida":["Лінія для літніх людей (Elpida)","Безкоштовна розмова, коли вам сумно або потрібна порада. Чеською."],"psych":["Лінія першої психологічної допомоги","Коли всього забагато. Безкоштовно, цілодобово, чеською."]},"cats":{"bezpeci":"Безпека онлайн","telefon":"Телефон і застосунки","internet":"Інтернет, повідомлення та мережі","penize":"Банк і платежі","urady":"Установи та лікар","pomoc":"Допомога й підтримка"},"urgent":{"krize":["не хочу жити","хочу померти","вбити себе","покінчити з собою","самогубств","зашкодити собі","немає сенсу жити"],"zdravi-nouze":["біль у грудях","болить у грудях","не можу дихати","задихаюся","інфаркт","інсульт","непритомн","знепритомнів","впав і не може встати","сильна кровотеча"],"uz-jsem-zadal":["ввів картку","ввела картку","натиснув посилання","натиснула посилання","надіслав гроші","надіслала гроші","мене ошукали","вкрали гроші"],"banka-vola":["безпечний рахунок","телефонує банк","служба безпеки банку","переказати гроші"]},"scam":{"card":"номер картки|дані картки|cvv|pin|пін|пароль|дані для входу|код підтвердження|код з sms|смс-код","urgent":"негайно|терміново|протягом 24|протягом 48|останнє попередження|сьогодні|закінчується|буде заблоковано|заблоковано|призупинено","fee":"збір|оплат|сплат|доплат|мито|платіж","parcel":"посилк|доставк|кур'єр|пошта|нова пошта|відправленн","bank":"банк|рахунок|поліці|податков|виконавч","safeacc":"безпечний рахунок|безпечного рахунку|переказати гроші|перекажіть","prize":"виграш|виграли|переможець|вітаємо|приз|подарунок|безкоштовно","family":"привіт мамо|мамо привіт|привіт тату|привіт бабусю|привіт дідусю|новий номер|загубив телефон|розбив телефон|надішли гроші","money":"гроші|грошей|надішли|переказ|позич","remote":"anydesk|teamviewer|rustdesk|віддален|встановіть програму|завантажте застосунок","invest":"інвестиці|інвестуй|крипто|біткоїн|bitcoin|прибут|гарантован|розбагат|пасивний дохід"}};
